INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 21, 'theory', 'Quiz: ride hailing');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 21, 0, 'Why aren''t driver positions written to an ordinary database?', '["Databases cannot store coordinates", "Hundreds of thousands of overwrites per second would kill the table, and old coordinates are not needed: you want an in-memory geo service with a TTL", "It is cheaper", "Positions are secret"]', 1, 'A write replaces the previous value, stale data expires by lifetime, and the history is written separately in batches.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 21, 1, 'How does the geo service find the nearest drivers?', '["It goes through all drivers", "It splits the map into cells and walks the passenger''s cell with its neighbors, widening the radius in rings", "It asks the passenger", "It uses a calendar"]', 1, 'Dense cells are split, and the geo service is sharded by cells.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 21, 2, 'How do you guarantee that one driver doesn''t get two orders?', '["Hope for luck", "The assignment is an atomic conditional update \"driver is free\" with an idempotent request", "Turn off the second passengers", "Send the order to everyone"]', 1, 'Competing assignments are cut off by the condition check at write time.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 21, 3, 'Why do payments need idempotency keys and pre-authorization?', '["For looks", "A repeated request to the provider doesn''t charge twice, and the amount is confirmed in advance", "For speed", "For encryption"]', 1, 'An external provider is slow and can make mistakes, so retries must be safe.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 21, 4, 'What does dividing the service into city cells give you?', '["More servers", "It limits the blast radius: a failure or a bad rollout affects one city", "Less code", "It removes databases"]', 1, 'The passenger and the driver are almost always in the same city, so the cells are nearly independent.');
